const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const k = tok[0], m = tok[1];
let p = 2;
const lists = [];
for (let i = 0; i < k; i++) {
  const len = tok[p++];
  lists.push(tok.slice(p, p + len));
  p += len;
}
// a binary min-heap of [value, list, position]; JavaScript has no built-in priority queue
const heap = [];
function push(x) {
  heap.push(x);
  let i = heap.length - 1;
  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (heap[parent][0] <= heap[i][0]) break;
    [heap[parent], heap[i]] = [heap[i], heap[parent]];
    i = parent;
  }
}
function pop() {
  const top = heap[0];
  const last = heap.pop();
  if (heap.length > 0) {
    heap[0] = last;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let s = i;
      if (l < heap.length && heap[l][0] < heap[s][0]) s = l;
      if (r < heap.length && heap[r][0] < heap[s][0]) s = r;
      if (s === i) break;
      [heap[s], heap[i]] = [heap[i], heap[s]];
      i = s;
    }
  }
  return top;
}
for (let i = 0; i < k; i++) if (lists[i].length > 0) push([lists[i][0], i, 0]);
const out = [];
while (heap.length > 0 && out.length < m) {
  const [v, i, j] = pop();
  out.push(v);
  if (j + 1 < lists[i].length) push([lists[i][j + 1], i, j + 1]);
}
console.log(out.join(' '));

