import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int k = (int) st.nval;
        st.nextToken();
        int m = (int) st.nval;
        long[][] lists = new long[k][];
        for (int i = 0; i < k; i++) {
            st.nextToken();
            int len = (int) st.nval;
            lists[i] = new long[len];
            for (int j = 0; j < len; j++) {
                st.nextToken();
                lists[i][j] = (long) st.nval;
            }
        }
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));   // {value, list, position}
        for (int i = 0; i < k; i++) if (lists[i].length > 0) pq.add(new long[]{lists[i][0], i, 0});
        StringBuilder sb = new StringBuilder();
        int taken = 0;
        while (!pq.isEmpty() && taken < m) {
            long[] top = pq.poll();
            if (taken > 0) sb.append(' ');
            sb.append(top[0]);
            taken++;
            int i = (int) top[1], j = (int) top[2];
            if (j + 1 < lists[i].length) pq.add(new long[]{lists[i][j + 1], i, j + 1});
        }
        System.out.println(sb);
    }
}

