#include <bits/stdc++.h>
using namespace std;
int main() {
    int k, m;
    scanf("%d %d", &k, &m);
    vector<vector<long long>> lists(k);
    for (int i = 0; i < k; i++) {
        int len;
        scanf("%d", &len);
        lists[i].resize(len);
        for (int j = 0; j < len; j++) scanf("%lld", &lists[i][j]);
    }
    typedef tuple<long long, int, int> T;                     // value, list, position
    priority_queue<T, vector<T>, greater<T>> pq;
    for (int i = 0; i < k; i++) if (!lists[i].empty()) pq.push(T(lists[i][0], i, 0));
    vector<long long> out;
    while (!pq.empty() && (int)out.size() < m) {
        auto [v, i, j] = pq.top();
        pq.pop();
        out.push_back(v);
        if (j + 1 < (int)lists[i].size()) pq.push(T(lists[i][j + 1], i, j + 1));
    }
    for (size_t i = 0; i < out.size(); i++) printf(i ? " %lld" : "%lld", out[i]);
    printf("\n");
    return 0;
}
